const form=document.getElementById('footer-admin-login');
form?.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button'),message=document.getElementById('footer-admin-error'),data=new FormData(form);button.disabled=true;message.textContent='';try{const response=await fetch('/api/admin/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Smerch-Admin':'1'},body:JSON.stringify({username:String(data.get('username')||'').trim(),password:String(data.get('password')||'')})});if(!response.ok){const result=await response.json();throw Error(result.error||'Login kunne ikke gennemføres.');}form.elements.password.value='';location.assign('/admin');}catch(error){form.elements.password.value='';message.textContent=error.message;button.disabled=false;}});
